  str_extra_mission_task_name_4500058 = "Ciudad del Viento",
  str_extra_mission_task_name_4500059 = "Al final",
  str_extra_mission_task_name_4500060 = "No como la primera vez",
  str_extra_mission_task_desc_4500001 = "En algún lugar de las afueras de Lumopolis, un grupo de asalto de Rediesel Wrench pasaba, con un botín abundante al parecer ...",
  str_extra_mission_task_desc_4500002 = "Estaba claro que un grupo de soldados ordinarios no calificados no serían rival para Brock, y su desprecio por ellos se podía ver desde millas de distancia.",
  str_extra_mission_task_desc_4500003 = "Con la intervención de dos Guardianes y la propia Carleen, Brock fue finalmente \"derrotado\" y arrojado a la Prisión de Lumopolis ...",
  str_extra_mission_task_desc_4500004 = "La compañía inesperada, Jona, logró escapar de la prisión con Brock. Parecía un poco loca, así que cruzaba los dedos esperando que no hiciera nada fuera de lugar...",
  str_extra_mission_task_desc_4500005 = "Solo a Jona se le ocurrió saltar de Lumopolis como medio de escape. Ante un escape tan atrevido, los Guardianes solo pudieron verlos partir.",
  str_extra_mission_task_desc_4500006 = "Brock se reunió con su equipo y juntos pudieron encontrarse con Regina, quien llegó como refuerzos. Sin embargo, un encuentro de eclipsites estaba ocurriendo cerca, y todos parecían estar preparándose para una pelea.",
  str_extra_mission_task_desc_4500007 = "La Subciudad de Illumina parecía estar invadida por los eclipsites, pero ¿por qué iban solo tras Sharona?",
  str_extra_mission_task_desc_4500008 = "Una vez más, el invitado no deseado había venido a burlarse de Sharona, y esta vez, algo importante parecía haber sido robado.",
  str_extra_mission_task_desc_4500009 = "Los dos tuvieron que comenzar a rastrear al enemigo. Deben averiguar qué fue robado. Este viaje no iba de ninguna manera como planeaban...",
  str_extra_mission_task_desc_4500010 = "Sharona tuvo que proteger a Philyshy que estaba dormida y lidiar con los ataques de los eclipsites. Definitivamente, esto no iba a ser fácil.",
  str_extra_mission_task_desc_4500011 = "¿Ya despierta, Philyshy parecía un poco extraña? ¿Y quién era \"Yumi\"? Sharona vaciló ante lo que vio ...",
  str_extra_mission_task_desc_4500012 = "Philyshy, que había logrado someter temporalmente a su otra personalidad, finalmente recordó que Bowlinger tenía lo que estaban buscando.",
  str_extra_mission_task_desc_4500013 = "Era una tarde de verano, y Connolly y su amigo Anton estaban limpiando el sótano del café cuando escucharon un misterioso grito de ayuda ...",
  str_extra_mission_task_desc_4500014 = "¡Los que alteren el orden del gremio deben ser severamente castigados! Robyn y Dayna aceptaron la misión, decididas a capturar al criminal.",
  str_extra_mission_task_desc_4500015 = "En su búsqueda del gato robot, Connolly y Anton llegaron al centro de lanzadera, y ante ellos estaban los Guardias Lumo ...",
  str_extra_mission_task_desc_4500016 = "¡La nueva víctima es el dueño del gato robot! Debe haber consumido la solución. ¡Debemos salvarlo!",
  str_extra_mission_task_desc_4500017 = "Los eclipsites, ocultos en las sombras, mordían las extremidades de la víctima inconsciente.",
  str_extra_mission_task_desc_4500018 = "¡Vendiendo productos prohibidos y atacando a miembros del Gremio! ¡Debemos averiguar quién está detrás de todo esto!",
  str_extra_mission_task_desc_4500019 = "Aquellos que se atrevan a entrar en Northland serán enterrados en la nieve helada sin rastro alguno.",
  str_extra_mission_task_desc_4500020 = "Carleen llegó a Northland sola a temprana edad. Los vientos árticos, en lugar de maravillas románticas, fueron los que la recibieron.",
  str_extra_mission_task_desc_4500021 = "Fracaso tras fracaso. Era simplemente un fantasma de eclipsite conjurado con magia, pero era inesperadamente formidable.",
  str_extra_mission_task_desc_4500022 = "En la pesadilla, Bethlehem revivió su pasado cuando Northland estaba al borde del colapso cuando innumerables eclipsites invadieron.",
  str_extra_mission_task_desc_4500023 = "La práctica persistente dio frutos. Identificar y aprovechar la debilidad del enemigo; ¡podría conducir a la victoria!",
  str_extra_mission_task_desc_4500024 = "¡Rompe el bloqueo final con la lanza en tus manos! ¡La esplendorosa aurora se convertirá en un puente que une a dos almas!",
  str_extra_mission_task_desc_4500001_long = "En algún lugar de las afueras de Lumopolis, una \"grupo de asalto\" de Rediesel Wrench pasaba ocurriendo, con un abundante botín al parecer.\nIncluso cuando se encontraron con la Patrulla de Lumopolis, su capitán, Brock, no vio la necesidad de entrar en pánico.De hecho, parecía como si estuviera ansioso por pelear.",
  str_extra_mission_task_desc_4500002_long = "Estaba claro que un grupo de soldados ordinarios no calificados no serían rival para Brock, ¡y su desprecio por ellos podía verse desde millas de distancia!\nSin embargo, con la intervención de dos Guardianes y la propia Carleen, Brock finalmente fue derrotado.",
  str_extra_mission_task_desc_4500003_long = "Brock fue arrojado a la prisión de Lumopolis, y fue aquí donde conoció a una compañera inesperada, Jona, quien, con aire despreocupado, ¡destruyó la instalación y escapó con Brock!",
  str_extra_mission_task_desc_4500004_long = "Jona parecía un poco loca, cruzaban los dedos esperando que no hiciera nada fuera de lugar...\nPor otra parte, ella saltó directamente de Lumopolis con Brock.\nDefinitivamente fue un intento de escape suicida.",
  str_extra_mission_task_desc_4500005_long = "Ante un escape tan atrevido, los Guardianes solo pudieron verlos partir.\nBrock se reunió con su equipo y juntos pudieron encontrarse con Regina, quien llegó como refuerzos.\nSin embargo, se estaba produciendo un encuentro eclipsite cerca, y todos parecían estar preparándose para una pelea.",
  str_extra_mission_task_desc_4500006_long = "Casualmente, los Guardianes también se vieron envueltos en la escaramuza, y ambos bandos acordaron dejar de lado sus diferencias para luchar contra el enemigo común.\nDespués de la batalla, cuando se enfrentó a Sinsa, el líder de Rediesel Wrench, Carleen dudaba en actuar, y solo pudo ver salir al grupo de locos ...",
  str_extra_mission_task_desc_4500007_long = "En la Subciudad de Illumina, Sharona fue despertada de su sueño por un extraño visitante,Quién parecía estar ahí solo para jugar con su cola.¿La Subciudad había sido invadida por enemigos?\n¿De qué se trataba todo esto?",
  str_extra_mission_task_desc_4500008_long = "El desconcertante visitante regresó y Sharona fue tras él, pero ¿era todo esto solo una distracción?\nDespués de derrotar a los súbditos, Sharona regresó a la Sala de Inteligencia y vio a Philyshy dormido ...Sharona no solo tuvo que aguantar que Philyshy perdiera información, ¡¿Ahora debía trabajar en equipo con ella también?!",
  str_extra_mission_task_desc_4500009_long = "Fue pura suerte que Philyshy encontrara el pasaje secreto.\nPhilyshy, que había protegido a Sharona, cambió la opinión de Sharona sobre ella.",
  str_extra_mission_task_desc_4500010_long = "Justo cuando las cosas estaban llegando a un punto crítico, ¡Philyshy no pudo evitar quedarse dormida de nuevo!\nLos enemigos que rápidamente vieron una oportunidad no la dejarían pasar.\nCuando Sharona comenzó a proteger a la pequeña, parecía estar creciendo un cariño por ...",
  str_extra_mission_task_desc_4500011_long = "Después de despertar, Philyshy era como una persona completamente diferente, cruel y excéntrica.\n¡Sharona la identificó de inmediato como la \"eclipsite\" que la había estado acosando!\n¿Sucedió esto debido al trastorno de identidad disociativa de Philyshy?\nPara despertar a Philyshy, Sharona tuvo que usar su cola para \"molestar al gato\".",
  str_extra_mission_task_desc_4500012_long = "Finalmente, Philyshy y Sharona llegaron juntas al final del pasadizo secreto, decididas a recuperar el objeto precioso robado: Que era una lata de pescado.\nResultó que bajo la influencia de Yumi, el plan del enemigo había fallado desde el principio ...\nSharona y Philyshy, por otro lado, fueron bendecidas con una amistad extraordinaria a partir de esta ridícula experiencia ...\n¿Y la eclipsite de alto nivel que apareció en Illumina fue...?",
  str_extra_mission_task_desc_4500013_long = "Era una tarde de verano y Connolly y su amigo Anton estaban limpiando el sótano del café.\nConnolly estaba reviviendo recuerdos del pasado después de encontrar una partitura llamada –Hogar– en el sótano,\ncuando un grito de ayuda vino de lo que resultó ser un gato robot.",
  str_extra_mission_task_desc_4500014_long = "¡El hombre misterioso que vendió la poción misteriosa y destruyó la orden del gremio había escapado!\nDespués de fracasar en su misión, Dayna y Robyn fueron al Café Holiday para tomar un descanso.\nDayna reparó al gato robot de Connolly con fuerza bruta,\npero antes de que pudiera disfrutar de su peluche, recibieron una nueva misión:\nY el gato también desapareció misteriosamente.",
  str_extra_mission_task_desc_4500015_long = "Siguiendo al gato robot, Connolly y Anton llegaron al centro de lanzadera.Fue aquí donde conocieron al dueño del gato robot, un hombre ansioso por entrar en Lumopolis, sin importar el costo.",
  str_extra_mission_task_desc_4500016_long = "Las palabras de Sheol dejaron a Connolly sumida en sus pensamientos. En el pasado, ella había estado inmersa en su propio mundo, sin saber que todos en Umbraton eran también familia suya.\nApareció un mensaje en el comunicador de Dayna: ¡Ha aparecido una nueva víctima!\nDecidida a conseguir la ayuda de todos, Connolly garabateó un mensaje para su familia en la pizarra.",
  str_extra_mission_task_desc_4500017_long = "Aun y cuando el dueño del gato se había bebido la solución, aún así murió y se convirtió en presa de los eclipsites.\nEn su alucinación, vio las puertas de Lumopolis abiertas de par en par frente a él,\npero el vacío en su corazón permaneció vacío.\nDespués de todo, Lumopolis nunca fue su hogar.",
  str_extra_mission_task_desc_4500018_long = "El eclipsite que vendió los bienes prohibidos cumplió con lo que le correspondía.\nSin embargo, la casa del mecánico y su gato se derrumbó, y confió en el gato al cuidado de Connolly.\nNo era la Lumopolis celestial la que había salvado a Connolly, ¡sino todos los que la rodeaban!\n\"¡Gracias! ¡Volvamos al café y tomemos un capuchino!\"",
  str_extra_mission_task_desc_4500019_long = "Northland es un reino donde la nieve nunca se derrite.\nEl poder devastador de las heladas y la nieve hizo que la Reina del Norte fuera invencible contra cualquier invasor;\nsin embargo, el mismo poder también la hizo prisionera..\nUn forastero se aproximaba mientras un inesperado copo de nieve cayendo.",
  str_extra_mission_task_desc_4500020_long = "\"No hagas nada inapropiado\".\nPadre hizo arreglos para enviar a Carleen sola a Northland.\nLa reina parecía distante, indiferente, fría como el hielo.\nComo forastera en tierra extranjera, Carleen sintió la soledad y el frío en su propia médula.",
  str_extra_mission_task_desc_4500021_long = "Podría ser alguna forma de profecía.\nBethlehem lo vio. La aurora, brillante pero tenue, brillaba en la oscuridad ilimitada de la noche.\nEn la tormenta, la joven Carleen intentó atacar al fantasma eclipsite, una y otra vez. Pero solo resultó en más fracasos.",
  str_extra_mission_task_desc_4500022_long = "La pesadilla perdida resurgió. Bethlehem vio el fantasma de sí misma.\nAdemás de eso, vio a Carleen.\n\"El poder viene con la soledad\". Aún así, Bethlehem aceptó el poder de las heladas y la nieve.\n¿Y Carleen? En la misma intersección, ¿qué camino elegiría caminar?",
  str_extra_mission_task_desc_4500023_long = "Llegar a ser poderoso requiere un gran esfuerzo.\nDel mismo modo, la cristalización de un hermoso copo de nieve requiere un frío extremo.\nCarleen lo hizo.\nCon una sonrisa de satisfacción, Bethlehem le pidió a Carleen que se preparara para el próximo \"juicio real\" ...",
  str_extra_mission_task_desc_4500024_long = "Fue la primera vez que Carleen derrotó a un eclipsite por sí misma.\nDespués de la tensión, Bethlehem acarició suavemente la cabeza de la joven.\nHizo un gesto hacia la esplendorosa aurora.\nPara proteger la aurora, eligió voluntariamente el poder y la soledad.\nCarleen compartió el sentimiento, razón por la cual tomó el mismo camino para proteger Lumopolis.",
  str_extra_mission_dec_0001 = "Fue otro día ordinario, otro robo ordinario, para el poco inteligente miembro de Rediesel Wrench, Brock. Rodeado por los Ángeles Guardianes de Carleen, era natural que fuera capturado por Lumopolis. Sin embargo, detrás de la fría celda de la prisión le esperaba otra cara conocida: Jona, de Rediesel Wrench...",
  str_extra_mission_dec_0002 = "Era tarde en la noche en Gannon, y como el resto de Illumina, Sharona estaba durmiendo profundamente hasta que \"alguien\" le tocó la cola. Esta extraña perturbación se prolongó durante varios días, y cuando la harta Sharona consiguió por fin localizar al autor, se ganó un compañero aún más problemático en el proceso, Philyshy...",
  str_extra_mission_dec_0003 = "Era una tarde perezosa, y salía la melodía de -Home- de la vieja y amarillenta partitura. Desde las calles de Umbraton, una tímida joven, Connolly, miraba a Lumopolis. Era un magnífico palacio, un paraíso para los creyentes, y un lugar donde residir, pero no era un hogar, especialmente para un viajero solitario...",
  str_extra_mission_dec_0004 = "Cubierta por el hielo y la nieve, la Tierra del Norte estuvo aislada durante generaciones del mundo exterior. La puerta del palacio de la reina estaba cerrada a cal y canto, como su frígido corazón. Sin embargo, esa pesada puerta fue abierta inesperadamente por un suave copo de nieve, que era pequeño pero firme, siempre mirando hacia la aurora."
}
return config
